{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a small patch of dirt and sparse grass. Its entire body except the back is covered in dense, shaggy brown fur that is darker on the legs and back and lighter tan on the muzzle, chest and flank. The head is bear-like with a black nose and small eyes, bearing a single long curved horn on the forehead and two small rounded ears. Four thick furry legs support the body and end in clawed paws, with a very short furry stub tail at the rear. Covering the dorsal surface from just behind the neck to above the tail is a large, highly glossy, dark reddish-brown to black segmented exoskeleton with overlapping plates and a raised shield over the shoulders.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, broad muzzle with lighter tan fur on muzzle and around eyes, black rounded nose at tip, small dark brown eyes, closed mouth, dense brown fur on cheeks and forehead",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single long slender glossy horn, dark reddish-brown to black with transverse ridged rings, tapering to a sharp point, curving upward and slightly backward",
      "where": "emerging from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears, brown, covered in short dense fur",
      "where": "on top of the head on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar muscular legs covered in long shaggy brown fur, darker brown on lower portions",
      "where": "two forelegs under the chest and two hind legs under the rump, extending vertically to the ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with long curved dark claws protruding from the fur at the toe tips",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short stubby furry tail, brown, covered in same fur as body",
      "where": "protruding from the rear of the body just below the posterior edge of the shell, on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large hard glossy exoskeleton, dark reddish-brown to black with strong specular highlights, smooth and reflective",
      "where": "covering the entire back from the shoulders to the rump, sitting atop the fur"
    },
    {
      "part": "plates",
      "looks_like": "overlapping transverse segmented plates forming the main shell, about eight visible segments with dark sutures between them, plus a larger anterior shoulder shield with two small pointed projections on its dorsal edge and a row of small circular pits along its ventral margin, and a lower lateral fringe of smaller plates each with an oval opening",
      "where": "composing the shell on the dorsal midline and along its lower edge"
    },
    {
      "part": "markings",
      "looks_like": "no distinct spots, stripes or patterns; fur shows gradation from dark brown on legs to lighter tan on chest, flank and muzzle; shell shows natural shading and highlight reflections but no painted markings",
      "where": "over the fur and shell surface"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
